latest.script:
function parseList(html, context) {
  var baseUrl = String(context.baseUrl || '').replace(/\/+$/, '');
  var doc = (typeof html === 'string') ? html : '';
  var results = [];
  var seen = {};
  var re = /<a\s[^>]*href="(\/comic\/detail\/(\d+))"([^>]*)>([\s\S]*?)<\/a>/gi;
  var m;
  while ((m = re.exec(doc)) !== null) {
    var id = m[2];
    if (seen[id]) continue;
    var attrs = m[3];
    var block = m[4];
    var title = '';
    var t = attrs.match(/title="([^"]*)"/i);
    if (t) title = t[1];
    if (!title) {
      var tm = block.match(/<span[^>]*class="[^"]*title[^"]*"[^>]*>([\s\S]*?)<\/span>/i);
      if (tm) title = tm[1].replace(/<[^>]+>/g, '').trim();
    }
    if (!title) continue;
    var cover = '';
    var cm = block.match(/data-src="([^"]+)"/i);
    if (cm) cover = cm[1];
    if (cover && cover.indexOf('loading') >= 0) cover = '';
    seen[id] = 1;
    results.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: baseUrl + '/comic/detail/' + id
    });
  }
  return results;
}

