detail.script:
function parseDetail(html, context) {
  var baseUrl = String(context.baseUrl || '').replace(/\/+$/, '');
  var doc = (typeof html === 'string') ? html : '';
  var strip = function (s) { return s.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim(); };
  var out = {};
  var m = doc.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  if (m) out.title = strip(m[1]);
  m = doc.match(/<img[^>]+class="[^"]*comic_cover[^"]*"[^>]*data-src="([^"]+)"/i);
  if (!m) m = doc.match(/<img[^>]+data-src="([^"]+)"[^>]*class="[^"]*comic_cover[^"]*"/i);
  if (m) out.cover = m[1];
  m = doc.match(/<meta[^>]+name="description"[^>]+content="([^"]*)"/i);
  if (!m) m = doc.match(/<meta[^>]+content="([^"]*)"[^>]+name="description"/i);
  if (m) out.description = m[1].trim();
  m = doc.match(/"author"\s*:\s*\{[^{}]*"name"\s*:\s*"([^"]+)"/i);
  if (m) out.author = m[1];
  m = doc.match(/<img[^>]+class="icon"[^>]*alt="([^"]*)"/i);
  if (m) out.status = m[1];
  var tags = [];
  var tr = /<a[^>]+href="[^"]*\?tag=\d+"[^>]*>([\s\S]*?)<\/a>/gi;
  while ((m = tr.exec(doc)) !== null) {
    var tag = strip(m[1]);
    if (tag && tags.indexOf(tag) < 0) tags.push(tag);
  }
  if (tags.length) out.tags = tags;
  return out;
}

chapters.script:
function parseChapters(html, context) {
  var baseUrl = String(context.baseUrl || '').replace(/\/+$/, '');
  var doc = (typeof html === 'string') ? html : '';
  var mid = (context.id == null) ? '' : String(context.id);
  var results = [];
  var seen = {};
  var re = /"name"\s*:\s*"((?:[^"\\]|\\.)*)"\s*,\s*"url"\s*:\s*"[^"]*\/comic\/chapter\/(\d+)"/g;
  var m;
  while ((m = re.exec(doc)) !== null) {
    var cid = m[2];
    if (seen[cid]) continue;
    seen[cid] = 1;
    var title = m[1].replace(/\\"/g, '"');
    results.push({
      id: mid ? mid + '@' + cid : cid,
      title: title,
      url: baseUrl + '/comic/chapter/' + cid
    });
  }
  return results;
}

images.script:
function parseImages(html, context) {
  var doc = (typeof html === 'string') ? html : '';
  var urls = [];
  var seen = {};
  var re = /data-src="([^"]*\/app\/comic\/[^"]+)"/gi;
  var m;
  while ((m = re.exec(doc)) !== null) {
    var u = m[1];
    if (seen[u]) continue;
    seen[u] = 1;
    urls.push(u);
  }
  return urls;
}
